import{_ as e,a as n,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"动态规划","description":"从一维递推学习状态，再按物品次数、连续性、区间依赖和集合状态选转移；保留跳跃游戏与回文中心扩展作为简化解法。","frontmatter":{"title":"动态规划","description":"从一维递推学习状态，再按物品次数、连续性、区间依赖和集合状态选转移；保留跳跃游戏与回文中心扩展作为简化解法。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"从一维递推学习状态，再按物品次数、连续性、区间依赖和集合状态选转移；保留跳跃游戏与回文中心扩展作为简化解法。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"编辑距离","link":"/principles/algorithms/dp/edit-distance"},"next":{"text":"多重背包","link":"/principles/algorithms/dp/knapsack-bounded"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"编辑距离","link":"/principles/algorithms/dp/edit-distance"},"next":{"text":"多重背包","link":"/principles/algorithms/dp/knapsack-bounded"}},"headers":[],"relativePath":"principles/algorithms/dp/algorithms-dp-general-general.md","filePath":"principles/algorithms/dp/algorithms-dp-general-general.md"}'),p={name:"principles/algorithms/dp/algorithms-dp-general-general.md"};function i(s,a,d,c,l,o){return n(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="动态规划" tabindex="-1">动态规划 <a class="header-anchor" href="#动态规划" aria-label="Permalink to &quot;动态规划&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>前置是循环、切片和递归；每个 package main 在独立模块中保存为 main.go（Go 1.22+），本轮未执行。n、容量、数量都非负，背包数组必须等长、重量为正，跳跃步数非负。矩阵链维度为正；TSP 输入是小规模完整费用矩阵，路径费用小于 inf 且加法不溢出，不把不可达哨兵直接当费用。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>递推只依赖前两个结果，或只判断最远可达</td><td><a href="#entry-fibonacci-dp-965e85d916">斐波那契</a>、<a href="#entry-climbing-stairs-89c05dec87">爬楼梯</a>、<a href="#entry-jump-game-2458489cdf">跳跃游戏</a></td><td>前两者可滚动保存状态；跳跃游戏示例是贪心，仅判断能否到达。</td></tr><tr><td>每件物品限一次、可无限次或有数量上限</td><td><a href="#entry-knapsack-01-3bac9dc3a2">0/1 背包</a>、<a href="#entry-knapsack-unbounded-921823aab7">完全背包</a>、<a href="#entry-knapsack-bounded-81c9519c7f">多重背包</a></td><td>0/1 容量倒序，完全背包正序且权重须为正，多重背包拆成二进制组。</td></tr><tr><td>比较序列顺序与连续片段</td><td><a href="#entry-lis-8d123a633c">LIS</a>、<a href="#entry-lcs-3576baa4db">LCS</a>、<a href="#entry-longest-common-substring-58fa479af8">最长公共子串</a></td><td>LIS 示例只返回长度；LCS 允许跳过字符，公共子串要求连续且失配归零。</td></tr><tr><td>计算修改字符串的最小代价或寻找回文</td><td><a href="#entry-edit-distance-8dec4540be">编辑距离</a>或<a href="#entry-longest-palindrome-535dd9e4cf">最长回文子串</a></td><td>编辑距离示例按字节计操作；回文示例用 rune 中心扩展，时间 O(n²)。</td></tr><tr><td>答案依赖连续子区间或孩子状态</td><td><a href="#entry-interval-dp-3b6beab63b">区间 DP</a>或<a href="#entry-tree-dp-f7762cdf8a">树形 DP</a></td><td>矩阵链按区间长度计算，时间 O(n³)；树形示例假设输入确为一棵树。</td></tr><tr><td>精确求解少量城市的最短回路</td><td><a href="#entry-bitmask-dp-922635c5db">状态压缩 DP</a></td><td>状态数 2ⁿ，示例时间 O(n²2ⁿ)，不适合大规模路线规划。</td></tr></tbody></table><h2 id="scene-start-with-recurrence" tabindex="-1">从滚动递推到最远可达判断 <a class="header-anchor" href="#scene-start-with-recurrence" aria-label="Permalink to &quot;从滚动递推到最远可达判断 {#scene-start-with-recurrence}&quot;">​</a></h2><h3 id="entry-fibonacci-dp-965e85d916" tabindex="-1">斐波那契动态规划 <a class="header-anchor" href="#entry-fibonacci-dp-965e85d916" aria-label="Permalink to &quot;斐波那契动态规划 {#entry-fibonacci-dp-965e85d916}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-fibonacci-dp-965e85d916-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/fibonacci-dp">斐波那契动态规划</a>。</p><p>朴素递归会重复计算大量相同子问题；滚动变量 a、b 分别保存前两个结果。每轮前进一项，既不需要递归栈也不需要完整数组。 时间 O(n)、额外空间 O(1)。</p><p>Go 的 int 会在数值过大时溢出，超大 n 应改用 math/big。</p><h3 id="entry-climbing-stairs-89c05dec87" tabindex="-1">爬楼梯 <a class="header-anchor" href="#entry-climbing-stairs-89c05dec87" aria-label="Permalink to &quot;爬楼梯 {#entry-climbing-stairs-89c05dec87}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-climbing-stairs-89c05dec87-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/climbing-stairs">爬楼梯</a>。</p><p>这里每次允许走 1 或 2 阶；允许更多步长时递推式也要随之改变。</p><h3 id="entry-jump-game-2458489cdf" tabindex="-1">跳跃游戏 <a class="header-anchor" href="#entry-jump-game-2458489cdf" aria-label="Permalink to &quot;跳跃游戏 {#entry-jump-game-2458489cdf}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-jump-game-2458489cdf-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/jump-game">跳跃游戏</a>。</p><p>这个贪心只判断能否到达，不计算最少跳跃次数。</p><h2 id="scene-choose-item-counts" tabindex="-1">按物品可用次数选择背包转移 <a class="header-anchor" href="#scene-choose-item-counts" aria-label="Permalink to &quot;按物品可用次数选择背包转移 {#scene-choose-item-counts}&quot;">​</a></h2><h3 id="entry-knapsack-01-3bac9dc3a2" tabindex="-1">0/1 背包 <a class="header-anchor" href="#entry-knapsack-01-3bac9dc3a2" aria-label="Permalink to &quot;0/1 背包 {#entry-knapsack-01-3bac9dc3a2}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-knapsack-01-3bac9dc3a2-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/knapsack-01">0/1 背包</a>。</p><p>dp[c] 表示容量不超过 c 时能得到的最大价值。处理某件物品时从大容量倒序更新，确保右侧读取的是“未用过当前物品”的旧状态。 每件物品最多选一次。</p><p>若正序更新，同一件物品可能在同轮被选多次，题意就变成完全背包。</p><h3 id="entry-knapsack-unbounded-921823aab7" tabindex="-1">完全背包 <a class="header-anchor" href="#entry-knapsack-unbounded-921823aab7" aria-label="Permalink to &quot;完全背包 {#entry-knapsack-unbounded-921823aab7}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-knapsack-unbounded-921823aab7-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/knapsack-unbounded">完全背包</a>。</p><p>权重必须为正；零重量且正价值的物品会让最优值无界。</p><h3 id="entry-knapsack-bounded-81c9519c7f" tabindex="-1">多重背包 <a class="header-anchor" href="#entry-knapsack-bounded-81c9519c7f" aria-label="Permalink to &quot;多重背包 {#entry-knapsack-bounded-81c9519c7f}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-knapsack-bounded-81c9519c7f-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/knapsack-bounded">多重背包</a>。</p><p>把物品数量按 1、2、4、…及余量拆成若干组，每组视为一件 0/1 物品。例如数量 5 拆为 1、2、2，可以组合出 0 到 5 的取用数量。这比逐件展开减少处理次数，但仍需保证组内重量和价值乘法不溢出。</p><h2 id="scene-compare-sequences" tabindex="-1">求递增序列、公共片段、编辑距离与回文 <a class="header-anchor" href="#scene-compare-sequences" aria-label="Permalink to &quot;求递增序列、公共片段、编辑距离与回文 {#scene-compare-sequences}&quot;">​</a></h2><h3 id="entry-lis-8d123a633c" tabindex="-1">最长递增子序列 <a class="header-anchor" href="#entry-lis-8d123a633c" aria-label="Permalink to &quot;最长递增子序列 {#entry-lis-8d123a633c}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-lis-8d123a633c-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/lis">最长递增子序列</a>。</p><p>tails[len−1] 保存某个长度的递增子序列可能达到的最小尾值。遇到新元素时，用二分找到第一个不小于它的位置并替换；这不会直接保存答案序列，但保留了未来延长的最好机会。 时间 O(n log n)。</p><p>要重建序列，还需记录前驱下标。</p><h3 id="entry-lcs-3576baa4db" tabindex="-1">最长公共子序列 <a class="header-anchor" href="#entry-lcs-3576baa4db" aria-label="Permalink to &quot;最长公共子序列 {#entry-lcs-3576baa4db}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-lcs-3576baa4db-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/lcs">最长公共子序列</a>。</p><p>dp[i][j] 考虑两个字符串各自的前 i、j 个字符。末尾字符相同就接在更短前缀的答案后；不同则分别跳过一侧末尾，取较大者。 时间 O(nm)。</p><p>子序列允许不连续，示例按 UTF-8 字节比较；按字符语义处理中文时应改成 rune。</p><h3 id="entry-longest-common-substring-58fa479af8" tabindex="-1">最长公共子串 <a class="header-anchor" href="#entry-longest-common-substring-58fa479af8" aria-label="Permalink to &quot;最长公共子串 {#entry-longest-common-substring-58fa479af8}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-longest-common-substring-58fa479af8-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/longest-common-substring">最长公共子串</a>。</p><p>示例按字节比较，处理 Unicode 字符时可先转成 rune 切片。</p><h3 id="entry-edit-distance-8dec4540be" tabindex="-1">编辑距离 <a class="header-anchor" href="#entry-edit-distance-8dec4540be" aria-label="Permalink to &quot;编辑距离 {#entry-edit-distance-8dec4540be}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-edit-distance-8dec4540be-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/edit-distance">编辑距离</a>。</p><p>dp[i][j] 是把第一个前缀改成第二个前缀所需的最少操作数。最后字符相同时沿对角线继承，否则在插入、删除和替换三种操作中取最小代价。 二维 DP 时间 O(nm)。</p><p>示例按字节计操作；中文字符级编辑距离应把输入转成 rune。</p><h3 id="entry-longest-palindrome-535dd9e4cf" tabindex="-1">最长回文子串 <a class="header-anchor" href="#entry-longest-palindrome-535dd9e4cf" aria-label="Permalink to &quot;最长回文子串 {#entry-longest-palindrome-535dd9e4cf}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-longest-palindrome-535dd9e4cf-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/longest-palindrome">最长回文子串</a>。</p><p>回文中心既可能是一个字符，也可能位于两个字符之间，因此每个位置尝试奇数和偶数两类中心。两侧字符相等时继续扩张，并记录最长范围。 中心扩展时间 O(n²)，转为 rune 切片占 O(n) 空间。</p><p>示例先转成 rune，能正确处理多字节字符；超大输入可改用线性时间的 Manacher 算法。</p><h2 id="scene-combine-subproblems" tabindex="-1">按区间或树结构汇总子问题 <a class="header-anchor" href="#scene-combine-subproblems" aria-label="Permalink to &quot;按区间或树结构汇总子问题 {#scene-combine-subproblems}&quot;">​</a></h2><h3 id="entry-interval-dp-3b6beab63b" tabindex="-1">区间 DP <a class="header-anchor" href="#entry-interval-dp-3b6beab63b" aria-label="Permalink to &quot;区间 DP {#entry-interval-dp-3b6beab63b}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-interval-dp-3b6beab63b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/interval-dp">区间 DP</a>。</p><p>矩阵链的子问题由连续区间 [l,r] 决定；只有更短区间已经算出，才能枚举切点 k 并组合左右最优代价。按区间长度递增填表满足这一依赖顺序。 目标是矩阵链最少乘法次数。</p><p>矩阵维度数组要满足相邻矩阵可以相乘，算法时间 O(n³)。</p><h3 id="entry-tree-dp-f7762cdf8a" tabindex="-1">树形 DP <a class="header-anchor" href="#entry-tree-dp-f7762cdf8a" aria-label="Permalink to &quot;树形 DP {#entry-tree-dp-f7762cdf8a}&quot;">​</a></h3><p><span id="输出-12"></span><span id="示例-12"></span></p><p><span id="entry-tree-dp-f7762cdf8a-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/tree-dp">树形 DP</a>。</p><p>对每个树节点分别计算“选当前节点”和“不选当前节点”两种状态。选中时孩子都不能选；不选时每个孩子可独立取较优状态。后序递归保证孩子先算好，最后取根的两种状态较大值。 示例求最大独立集权重。</p><p>示例假设输入是一棵树。</p><h2 id="scene-remember-visited-set" tabindex="-1">把已访问集合编码成状态 <a class="header-anchor" href="#scene-remember-visited-set" aria-label="Permalink to &quot;把已访问集合编码成状态 {#scene-remember-visited-set}&quot;">​</a></h2><h3 id="entry-bitmask-dp-922635c5db" tabindex="-1">状态压缩 DP <a class="header-anchor" href="#entry-bitmask-dp-922635c5db" aria-label="Permalink to &quot;状态压缩 DP {#entry-bitmask-dp-922635c5db}&quot;">​</a></h3><p><span id="输出-13"></span><span id="示例-13"></span></p><p><span id="entry-bitmask-dp-922635c5db-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/dp/bitmask-dp">状态压缩 DP</a>。</p><p>mask 的每一位表示某个城市是否已经访问，dp[mask][v] 表示访问该集合并停在 v 的最短长度。对每个未访问城市尝试转移，最后加上回到起点的费用。 示例求小规模旅行商最短回路，时间 O(n²2ⁿ)。</p><p>状态数为 2ⁿ，适合 n 较小的精确求解，不适合大规模路线规划。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>把 0/1 背包改成容量正序，单件重量 2、价值 3、容量 4 会得到多少？提示：看 dp[2] 是本轮还是上轮。</p><details class="details custom-block"><summary>参考解法</summary><p>会得到 6，而正确的限用一次结果为 3；本轮更新的 dp[2] 被再次使用，相当于允许重复选择。完全背包才使用这种正序转移。</p></details>',91)])])}const m=e(p,[["render",i]]);export{b as __pageData,m as default};
